// Showcase data: recorded real model replies and the numbers on the project page.
// Generated by scripts/build_showcase_data.py from committed reports; never edited by hand.
import data from "./data.json";

export interface RecordedReply {
  reply: string;
  stop_reason: string;
  new_tokens: number;
  content_check: boolean | null;
}

export interface RecordedConversation {
  id: string;
  category: string;
  turns: { role: "user" | "assistant"; content: string }[];
  replies: { m5: RecordedReply; m6_3: RecordedReply };
}

export const recorded = data.recorded as RecordedConversation[];
export const recordedSource: string = data.source.recorded;

const facts = data.facts as Record<string, { value: string; label: string }>;

/** A number shown on the project page; throws if it is not backed by docs/showcase/facts.json. */
export function fact(id: string): string {
  const f = facts[id];
  if (!f) throw new Error(`unknown fact ${id}`);
  return f.value;
}
